Object.assign(translations,{"selected":{"en":"selected","fr":"sélectionné(s)","ar":"محدد"},"Print internal labels":{"en":"Print internal labels","fr":"Imprimer étiquettes internes","ar":"طباعة ملصقات داخلية"},"Internal labels":{"en":"Internal labels","fr":"Étiquettes internes","ar":"ملصقات داخلية"},"Print":{"en":"Print","fr":"Imprimer","ar":"طباعة"},"Not an official Atlas label.":{"en":"Not an official Atlas label.","fr":"Ce n’est pas une étiquette officielle Atlas.","ar":"هذا ليس ملصق أطلس الرسمي."},"Allow popups to print labels.":{"en":"Allow popups to print labels.","fr":"Autorisez les fenêtres contextuelles pour imprimer.","ar":"اسمح بالنوافذ المنبثقة للطباعة."},"Atlas API documentation required.":{"en":"Atlas API documentation required.","fr":"Documentation API Atlas nécessaire.","ar":"خاص توثيق API أطلس."},"Prepare from stock":{"en":"Prepare from stock","fr":"À préparer du stock","ar":"للتحضير من المخزون"},"Remove preparation":{"en":"Remove preparation","fr":"Retirer « à préparer »","ar":"إزالة من التحضير"},"Delete":{"en":"Delete","fr":"Supprimer","ar":"حذف"},"Deselect":{"en":"Deselect","fr":"Désélectionner","ar":"إلغاء التحديد"},"Atlas Confirm and preparation require additional Atlas API documentation. Labels here are internal, not official Atlas labels.":{"en":"Atlas Confirm and preparation require additional Atlas API documentation. Labels here are internal, not official Atlas labels.","fr":"Atlas Confirm et la préparation nécessitent une documentation API Atlas complémentaire. Les étiquettes ici sont internes, pas les étiquettes officielles Atlas.","ar":"Atlas Confirm والتحضير خاصهم توثيق إضافي من أطلس. الملصقات هنا داخلية وماشي ملصقات أطلس الرسمية."},"Confirm cancellation?":{"en":"Confirm cancellation?","fr":"Confirmer l’annulation ?","ar":"تأكيد الإلغاء؟"},"Atlas only allows deleting new parcels not being prepared. Atlas restores reserved stock. Local history is kept.":{"en":"Atlas only allows deleting new parcels not being prepared. Atlas restores reserved stock. Local history is kept.","fr":"Atlas autorise uniquement les colis nouveaux hors préparation. Atlas restitue le stock réservé. L’historique local est conservé.","ar":"أطلس كتسمح غير بإلغاء الكوليات الجديدة اللي ما بداتش التحضير. أطلس كترجع المخزون المحجوز والتاريخ كيبقى فالمنصة."},"Processing…":{"en":"Processing…","fr":"Traitement…","ar":"جاري التنفيذ…"},"Confirm deletion":{"en":"Confirm deletion","fr":"Confirmer la suppression","ar":"تأكيد الحذف"},"Cancel":{"en":"Cancel","fr":"Annuler","ar":"إلغاء"},"Cancelled":{"en":"Cancelled","fr":"Annulées","ar":"ملغاة"},"Order cannot be cancelled.":{"en":"Order cannot be cancelled.","fr":"Cette commande ne peut pas être annulée.","ar":"لا يمكن إلغاء هذا الطلب."},"Select visible orders":{"en":"Select visible orders","fr":"Sélectionner les commandes affichées","ar":"تحديد الطلبات الظاهرة"},"Select order":{"en":"Select order","fr":"Sélectionner la commande","ar":"تحديد الطلب"}});
Object.assign(translations,{"Atlas stock":{"en":"Atlas stock","fr":"Stock Atlas","ar":"مخزون أطلس"},"All products returned by Atlas, including out-of-stock and frozen items. Read-only: no changes to your Atlas stock.":{"en":"All products returned by Atlas, including out-of-stock and frozen items. Read-only: no changes to your Atlas stock.","fr":"Tous les articles renvoyés par Atlas, y compris les articles épuisés et gelés. Consultation uniquement : aucun changement du stock Atlas.","ar":"جميع المنتوجات اللي كيرجعها أطلس، حتى النافدة والمجمّدة. عرض فقط بلا تغيير المخزون."},"Unable to load Atlas inventory.":{"en":"Unable to load Atlas inventory.","fr":"Impossible de charger le stock Atlas.","ar":"تعذّر تحميل مخزون أطلس."},"Showing the last successful stock snapshot.":{"en":"Showing the last successful stock snapshot.","fr":"Les dernières données récupérées sont affichées.","ar":"كتبان آخر بيانات تم تحميلها بنجاح."},"Atlas products":{"en":"Atlas products","fr":"Articles Atlas","ar":"منتوجات أطلس"},"Available units":{"en":"Available units","fr":"Unités disponibles","ar":"الوحدات المتوفرة"},"Out of stock":{"en":"Out of stock","fr":"Épuisé","ar":"نافد"},"Frozen stock":{"en":"Frozen stock","fr":"Stock gelé","ar":"مخزون مجمّد"},"Full Atlas catalogue":{"en":"Full Atlas catalogue","fr":"Catalogue Atlas complet","ar":"كتالوج أطلس الكامل"},"Last refresh":{"en":"Last refresh","fr":"Dernière actualisation","ar":"آخر تحديث"},"Not loaded yet":{"en":"Not loaded yet","fr":"Pas encore chargé","ar":"مازال ما تحمّلش"},"Stock status":{"en":"Stock status","fr":"État du stock","ar":"حالة المخزون"},"In stock":{"en":"In stock","fr":"Disponible","ar":"متوفر"},"Search Atlas stock":{"en":"Search Atlas stock","fr":"Rechercher dans le stock Atlas","ar":"البحث فمخزون أطلس"},"Product, SKU…":{"en":"Product, SKU…","fr":"Produit, SKU…","ar":"المنتوج، المرجع…"},"Atlas stock ID":{"en":"Atlas stock ID","fr":"Identifiant stock Atlas","ar":"معرّف المخزون في أطلس"},"Atlas returned no stock products.":{"en":"Atlas returned no stock products.","fr":"Atlas n’a renvoyé aucun article de stock.","ar":"أطلس ما رجّعات حتى منتوج فالمخزون."},"Refreshes every minute while this page is open.":{"en":"Refreshes every minute while this page is open.","fr":"Actualisation chaque minute tant que cette page est ouverte.","ar":"كيتحدّث كل دقيقة ما دام هاد القسم محلول."}});
