Object.assign(translations,{"LIVRAISON":{"en":"LIVRAISON","fr":"LIVRAISON","ar":"التوصيل"},"STOCK & ENTREPÔT":{"en":"STOCK & ENTREPÔT","fr":"STOCK & ENTREPÔT","ar":"المخزون والمستودع"},"FINANCE":{"en":"FINANCE","fr":"FINANCE","ar":"المالية"},"BOUTIQUE & COMPTE":{"en":"BOUTIQUE & COMPTE","fr":"BOUTIQUE & COMPTE","ar":"المتجر والحساب"},"Colis":{"en":"Colis","fr":"Colis","ar":"الطلبات"},"Tableau de bord":{"en":"Tableau de bord","fr":"Tableau de bord","ar":"لوحة التحكم"},"Costs & prices":{"en":"Costs & prices","fr":"Coûts & prix","ar":"التكاليف والأثمنة"},"TEAM WORKSPACE":{"en":"TEAM WORKSPACE","fr":"ESPACE ÉQUIPE","ar":"فضاء الفريق"},"Close menu":{"en":"Close menu","fr":"Fermer le menu","ar":"إغلاق القائمة"},"Open menu":{"en":"Open menu","fr":"Ouvrir le menu","ar":"فتح القائمة"},"Main menu":{"en":"Main menu","fr":"Menu principal","ar":"القائمة الرئيسية"},"Connected to Atlas API":{"en":"Connected to Atlas API","fr":"Intégration API Atlas","ar":"ربط API أطلس"},"Change theme":{"en":"Change theme","fr":"Changer le thème","ar":"تغيير المظهر"},"Grid view":{"en":"Grid view","fr":"Vue en grille","ar":"عرض البطاقات"},"List view":{"en":"List view","fr":"Vue en liste","ar":"عرض القائمة"}});
Object.assign(translations,{"Profit and acquisition cost by agent":{"en":"Profit and acquisition cost by agent","fr":"Rentabilité et coût d’acquisition par collaboratrice","ar":"الربح وتكلفة الاستقطاب ديال كل بنت"},"Business profit is separate from the agent’s 10 DH commission.":{"en":"Business profit is separate from the agent’s 10 DH commission.","fr":"Le profit de l’entreprise est distinct de la commission de 10 DH de la collaboratrice.","ar":"ربح التجارة منفصل على عمولة البنت ديال 10 دراهم."},"Lead = one order entered in this platform, including drafts and cancellations. CPL = assigned ad spend / leads; cost per delivered order = assigned ad spend / delivered orders.":{"en":"Lead = one order entered in this platform, including drafts and cancellations. CPL = assigned ad spend / leads; cost per delivered order = assigned ad spend / delivered orders.","fr":"Lead = une commande saisie sur cette plateforme, brouillons et annulations inclus. CPL = publicité attribuée / leads ; coût par livré = publicité attribuée / commandes livrées.","ar":"Lead = طلب تسجّل فهاد المنصة، بما فيه المسودات والملغاة. CPL = الإشهار المنسوب للبنت ÷ طلباتها؛ التكلفة لكل مسلّم = نفس الإشهار ÷ الطلبات المسلّمة."},"Profit = delivered sales minus purchase costs, transport, commissions and assigned advertising. Unassigned advertising is not deducted from individual profit.":{"en":"Profit = delivered sales minus purchase costs, transport, commissions and assigned advertising. Unassigned advertising is not deducted from individual profit.","fr":"Profit = ventes livrées − achats − transport − commissions − publicité attribuée. La publicité non attribuée n’est pas déduite du profit individuel.","ar":"الربح = مبيعات الطلبات المسلّمة ناقص الشراء والنقل والعمولات والإشهار المنسوب. الإشهار العام ما كيتنقصش من الربح الفردي."},"Advertising not assigned to an agent:":{"en":"Advertising not assigned to an agent:","fr":"Publicité non attribuée à une collaboratrice :","ar":"الإشهار اللي ما تنسب حتى لبنت:"},"Assigned ad spend":{"en":"Assigned ad spend","fr":"Publicité attribuée","ar":"الإشهار المنسوب"},"Cost per lead":{"en":"Cost per lead","fr":"Coût par lead (CPL)","ar":"التكلفة لكل طلب (CPL)"},"Ad cost per delivered order":{"en":"Ad cost per delivered order","fr":"Coût pub par livré","ar":"تكلفة الإشهار لكل طلب مسلّم"},"Profit after assigned ads":{"en":"Profit after assigned ads","fr":"Profit après publicité attribuée","ar":"الربح بعد الإشهار المنسوب"},"Leads / orders entered":{"en":"Leads / orders entered","fr":"Leads / commandes saisies","ar":"الطلبات المدخلة / Leads"},"Not entered":{"en":"Not entered","fr":"Non saisi","ar":"ما تسجّلش"},"Ads not assigned":{"en":"Ads not assigned","fr":"Publicité non renseignée","ar":"الإشهار ما تسجّلش"},"Enter ad spend in Finance and select the agent. Enter 0 DH to record a period with no advertising.":{"en":"Enter ad spend in Finance and select the agent. Enter 0 DH to record a period with no advertising.","fr":"Saisissez les publicités dans Finance en sélectionnant la collaboratrice. Saisissez 0 DH pour déclarer une période sans publicité.","ar":"سجّل مصاريف الإشهار فـFinance واختار البنت. دخل 0 درهم إلا كانت الفترة بلا إشهار."},"— means no ad entry or a zero denominator. ≈ means estimated transport.":{"en":"— means no ad entry or a zero denominator. ≈ means estimated transport.","fr":"— : publicité non saisie ou dénominateur nul. ≈ : transport estimé.","ar":"— : الإشهار ما تسجّلش أو المقسوم عليه صفر. ≈ : النقل تقديري."},"Assign advertising to an agent":{"en":"Assign advertising to an agent","fr":"Attribuer la publicité à une collaboratrice","ar":"نسب الإشهار لبنت"},"Unassigned to an agent":{"en":"Unassigned to an agent","fr":"Non attribuée à une collaboratrice","ar":"غير منسوب لبنت"},"Advertising not assigned to a product:":{"en":"Advertising not assigned to a product:","fr":"Publicité non attribuée à un produit :","ar":"إشهار غير منسوب لمنتوج:"}});
Object.assign(translations,{"Team charts":{"en":"Team charts","fr":"Diagrammes de l’équipe","ar":"دياغرامات الفريق"},"Charts appear when team accounts are added. No sample data is displayed.":{"en":"Charts appear when team accounts are added. No sample data is displayed.","fr":"Les diagrammes apparaîtront après l’ajout des collaboratrices. Aucune donnée fictive n’est affichée.","ar":"الدياغرامات غيبانو ملي تزيد حسابات البنات. ما كايناش بيانات تجريبية."},"Orders vs deliveries by agent":{"en":"Orders vs deliveries by agent","fr":"Commandes et livraisons par collaboratrice","ar":"الطلبات والمسلّمة ديال كل بنت"},"Entered orders and delivered orders, shown side by side, not stacked.":{"en":"Entered orders and delivered orders, shown side by side, not stacked.","fr":"Commandes saisies et livrées, comparées côte à côte, sans cumul.","ar":"مقارنة الطلبات المدخلة والمسلّمة جنباً لجنب، بلا جمعهم."},"Profit by agent":{"en":"Profit by agent","fr":"Profit par collaboratrice","ar":"الربح ديال كل بنت"},"After assigned advertising; red bars indicate a loss. ≈ includes estimated transport.":{"en":"After assigned advertising; red bars indicate a loss. ≈ includes estimated transport.","fr":"Après publicité attribuée ; le rouge indique une perte. ≈ inclut du transport estimé.","ar":"بعد الإشهار المنسوب؛ الأحمر كيعني خسارة. ≈ فيه نقل تقديري."},"Acquisition cost by agent":{"en":"Acquisition cost by agent","fr":"Coût d’acquisition par collaboratrice","ar":"تكلفة الاستقطاب ديال كل بنت"},"Assigned advertising divided by entered orders or delivered orders.":{"en":"Assigned advertising divided by entered orders or delivered orders.","fr":"Publicité attribuée divisée par les commandes saisies ou livrées.","ar":"الإشهار المنسوب مقسوم على الطلبات المدخلة أو المسلّمة."},"Delivery rate by agent":{"en":"Delivery rate by agent","fr":"Taux de livraison par collaboratrice","ar":"نسبة التوصيل ديال كل بنت"},"Delivered orders / orders transmitted to Atlas.":{"en":"Delivered orders / orders transmitted to Atlas.","fr":"Commandes livrées / commandes transmises à Atlas.","ar":"الطلبات المسلّمة ÷ الطلبات المرسلة لأطلس."},"— = missing data, not zero. Click an agent’s name to view her orders.":{"en":"— = missing data, not zero. Click an agent’s name to view her orders.","fr":"— = donnée manquante, pas zéro. Cliquez sur le nom pour voir ses commandes.","ar":"— = بيانات ناقصة، ماشي صفر. ضغط على سمية البنت باش تشوف طلباتها."}});
Object.assign(translations,{"The green arc shows delivered orders as a share of all entered orders.":{"en":"The green arc shows delivered orders as a share of all entered orders.","fr":"L’arc vert indique la part livrée parmi toutes les commandes saisies.","ar":"القوس الأخضر كيبين نسبة المسلّمة من جميع الطلبات المدخلة."},"Money amounts, not percentages. Red indicates a loss; ≈ includes estimated transport.":{"en":"Money amounts, not percentages. Red indicates a loss; ≈ includes estimated transport.","fr":"Montants en DH, pas des pourcentages. Rouge : perte ; ≈ : transport estimé.","ar":"مبالغ بالدرهم، ماشي نِسب مئوية. الأحمر خسارة؛ ≈ نقل تقديري."},"CPL and cost per delivered order in DH, displayed as circular indicators.":{"en":"CPL and cost per delivered order in DH, displayed as circular indicators.","fr":"CPL et coût par livré en DH, présentés sous forme d’indicateurs circulaires.","ar":"CPL والتكلفة لكل طلب مسلّم بالدرهم، على شكل مؤشرات دائرية."}});
Object.assign(translations,{"Product purchase costs":{"en":"Product purchase costs","fr":"Coût des produits","ar":"تكلفة شراء المنتوجات"},"Choose a period, enter product costs and dated advertising spend, then view the calculated profit.":{"en":"Choose a period, enter product costs and dated advertising spend, then view the calculated profit.","fr":"Choisissez une période, saisissez les coûts des produits et les publicités datées, puis consultez le profit calculé.","ar":"اختار الفترة، سجّل تكلفة المنتوجات والإشهار بالتاريخ ديالو، وشوف الربح المحسوب."},"View period profit":{"en":"View period profit","fr":"Voir le profit de la période","ar":"شوف ربح الفترة"},"One unit purchase cost per SKU. The cost of a delivered order is unit cost × quantity. Saving updates new orders only; recorded historical costs are not overwritten.":{"en":"One unit purchase cost per SKU. The cost of a delivered order is unit cost × quantity. Saving updates new orders only; recorded historical costs are not overwritten.","fr":"Un coût d’achat unitaire par SKU. Coût d’une commande livrée = coût unitaire × quantité. La sauvegarde concerne les nouvelles commandes ; les coûts historiques déjà enregistrés ne sont pas remplacés.","ar":"تكلفة الشراء للوحدة حسب SKU. تكلفة الطلب المسلّم = تكلفة الوحدة × الكمية. الحفظ كيتطبّق على الطلبات الجديدة، ما كيبدّلش التكاليف القديمة المسجّلة."},"For older orders without a purchase cost, preview and confirm filling the missing cost within the selected period. Matching uses the product ID or exact Atlas SKU, never the product name.":{"en":"For older orders without a purchase cost, preview and confirm filling the missing cost within the selected period. Matching uses the product ID or exact Atlas SKU, never the product name.","fr":"Pour les anciennes commandes sans coût, prévisualisez puis confirmez le complément dans la période choisie. Correspondance par identifiant produit ou SKU Atlas exact, jamais par nom.","ar":"للطلبات القديمة بلا تكلفة شراء، راجع وأكّد تعمير التكلفة الناقصة داخل الفترة المختارة. الربط بمعرّف المنتوج أو SKU أطلس مطابق، ماشي بالاسم."},"Atlas catalogue unavailable. Saved product costs are still shown.":{"en":"Atlas catalogue unavailable. Saved product costs are still shown.","fr":"Catalogue Atlas indisponible. Les coûts déjà enregistrés restent affichés.","ar":"كتالوج أطلس ما متوفرش دابا. التكاليف المسجّلة كتبقى باينة."},"Product cost saved for new orders.":{"en":"Product cost saved for new orders.","fr":"Coût enregistré pour les nouvelles commandes.","ar":"تسجّلات التكلفة للطلبات الجديدة."},"Missing order costs updated:":{"en":"Missing order costs updated:","fr":"Coûts manquants complétés :","ar":"التكاليف الناقصة اللي تعمّرات:"},"Confirm missing cost update":{"en":"Confirm missing cost update","fr":"Confirmer le complément des coûts","ar":"تأكيد تعمير التكاليف الناقصة"},"unit":{"en":"unit","fr":"unité","ar":"وحدة"},"orders without purchase cost":{"en":"orders without purchase cost","fr":"commandes sans coût d’achat","ar":"طلبات بلا تكلفة شراء"},"Only these missing costs will be filled. Existing recorded costs, Atlas stock and parcel details are unchanged. Up to 200 orders per batch.":{"en":"Only these missing costs will be filled. Existing recorded costs, Atlas stock and parcel details are unchanged. Up to 200 orders per batch.","fr":"Seuls ces coûts manquants seront complétés. Coûts déjà enregistrés, stock Atlas et détails des colis inchangés. Maximum 200 commandes par lot.","ar":"غير هاد التكاليف الناقصة اللي غيتعمّرو. التكاليف المسجّلة ومخزون أطلس وتفاصيل الكولي ما كيتبدّلوش. حتى لـ200 طلب فالدفعة."},"Confirm and apply":{"en":"Confirm and apply","fr":"Confirmer et appliquer","ar":"تأكيد وتطبيق"},"Fill missing costs in this period":{"en":"Fill missing costs in this period","fr":"Compléter les coûts de cette période","ar":"عمّر التكلفة الناقصة فهاد الفترة"},"Product cost changed. Preview again before applying.":{"en":"Product cost changed. Preview again before applying.","fr":"Le coût a changé. Prévisualisez de nouveau avant d’appliquer.","ar":"تكلفة المنتوج تبدّلات. عاود المعاينة قبل التطبيق."},"Only advertising dated within the selected period is deducted from that period’s profit.":{"en":"Only advertising dated within the selected period is deducted from that period’s profit.","fr":"Seules les publicités datées dans la période sélectionnée sont déduites de son profit.","ar":"غير مصاريف الإشهار المؤرّخة داخل الفترة المختارة هي اللي كتتنقص من ربحها."}});
Object.assign(translations,{'Swipe tables horizontally to see all columns.':{en:'Swipe tables horizontally to see all columns.',fr:'Glissez les tableaux horizontalement pour voir toutes les colonnes.',ar:'جرّ الجدول لليمين أو لليسار باش تشوف جميع الأعمدة.'}});
Object.assign(translations,{"Outstanding commissions · all time":{"en":"Outstanding commissions · all time","fr":"Commissions à payer · depuis le début","ar":"العمولات الباقية للأداء · من البداية"},"This is the remaining balance, not lifetime earned commission.":{"en":"This is the remaining balance, not lifetime earned commission.","fr":"Solde restant à payer après les paiements enregistrés.","ar":"هاد المبلغ هو الباقي للأداء من بعد الأداءات المسجّلة."},"Earned commission":{"en":"Earned commission","fr":"Commission acquise","ar":"العمولة المكتسبة"},"Commission paid":{"en":"Commission paid","fr":"Commission payée","ar":"العمولة المؤدّاة"},"Commission remaining":{"en":"Commission remaining","fr":"Commission à payer","ar":"العمولة الباقية للأداء"},"Commission credit":{"en":"Commission credit","fr":"Avance de commission","ar":"تسبيق العمولة"},"10 DH is earned once per delivered order. Marking paid only records an external payment; no money is transferred. Payment records are kept and are not deducted again from business profit.":{"en":"10 DH is earned once per delivered order. Marking paid only records an external payment; no money is transferred. Payment records are kept and are not deducted again from business profit.","fr":"10 DH par commande livrée. « Marquer payé » enregistre un paiement déjà effectué ailleurs, sans transfert d’argent. L’historique est conservé ; les paiements ne sont pas déduits une seconde fois du profit.","ar":"10 دراهم لكل طلب مسلّم. «تسجيل الأداء» كيسجّل أداء تدار خارج المنصة، بلا تحويل فلوس. السجل كيبقى والأداء ما كيتنقصش مرة ثانية من الربح."},"Balances are all-time. If Atlas corrects a previously paid delivery, the payment stays in history and any excess appears as credit against future commissions.":{"en":"Balances are all-time. If Atlas corrects a previously paid delivery, the payment stays in history and any excess appears as credit against future commissions.","fr":"Soldes depuis le début. Si Atlas corrige une livraison déjà payée, le paiement reste dans l’historique et l’excédent devient une avance sur les prochaines commissions.","ar":"الأرصدة محسوبة من البداية. إلا صحّحات أطلس تسليم سبق تخلّص، الأداء كيبقى فالسجل والزيادة كتولي تسبيق على العمولات الجاية."},"Payment recorded. The outstanding balance has been reduced.":{"en":"Payment recorded. The outstanding balance has been reduced.","fr":"Paiement enregistré. Le solde à payer a diminué.","ar":"تسجّل الأداء وتنقص الرصيد الباقي."},"Partly paid":{"en":"Partly paid","fr":"Partiellement payée","ar":"مؤدّاة جزئياً"},"Unpaid":{"en":"Unpaid","fr":"Non payée","ar":"غير مؤدّاة"},"Paid":{"en":"Paid","fr":"Payée","ar":"مؤدّاة"},"No earned commission":{"en":"No earned commission","fr":"Aucune commission acquise","ar":"ما كايناش عمولة مكتسبة"},"Confirm commission payment":{"en":"Confirm commission payment","fr":"Confirmer le paiement de commission","ar":"تأكيد أداء العمولة"},"Payment note / reference":{"en":"Payment note / reference","fr":"Note / référence du paiement","ar":"ملاحظة أو مرجع الأداء"},"I confirm that I have already paid this amount outside the platform.":{"en":"I confirm that I have already paid this amount outside the platform.","fr":"Je confirme avoir déjà payé ce montant en dehors de la plateforme.","ar":"كنأكد بلي خلّصت هاد المبلغ خارج المنصة."},"Confirm paid":{"en":"Confirm paid","fr":"Confirmer payé","ar":"تأكيد الأداء"},"Commission balances by agent":{"en":"Commission balances by agent","fr":"Commissions par collaboratrice","ar":"العمولات ديال كل بنت"},"Payment status":{"en":"Payment status","fr":"Statut du paiement","ar":"حالة الأداء"},"Mark paid":{"en":"Mark paid","fr":"Marquer payé","ar":"تسجيل الأداء"},"Commission payment history":{"en":"Commission payment history","fr":"Historique des paiements de commissions","ar":"سجل أداءات العمولات"},"Latest 100 payments":{"en":"Latest 100 payments","fr":"100 derniers paiements","ar":"آخر 100 أداء"},"No commission payment recorded yet.":{"en":"No commission payment recorded yet.","fr":"Aucun paiement de commission enregistré.","ar":"ما تسجّل حتى أداء ديال العمولة."},"Payment reference already used.":{"en":"Payment reference already used.","fr":"Référence de paiement déjà utilisée.","ar":"مرجع الأداء مستعمل من قبل."},"Commission balance changed. Refresh before confirming payment.":{"en":"Commission balance changed. Refresh before confirming payment.","fr":"Le solde a changé. Actualisez avant de confirmer le paiement.","ar":"الرصيد تبدّل. حدّث الصفحة قبل تأكيد الأداء."}});
Object.assign(translations,{"Transport costs come only from Atlas and are refreshed with shipment synchronization. Missing Atlas fees keep profit incomplete.":{"en":"Transport costs come only from Atlas and are refreshed with shipment synchronization. Missing Atlas fees keep profit incomplete.","fr":"Les frais de transport proviennent uniquement d’Atlas et sont actualisés lors de la synchronisation des colis. Sans frais Atlas, le profit reste incomplet.","ar":"مصاريف النقل كتتاخد غير من أطلس وكتتحدّث مع مزامنة الكوليات. إلا ما رجعاتش التكلفة، الربح كيبقى غير مكتمل."},"Awaiting Atlas":{"en":"Awaiting Atlas","fr":"En attente d’Atlas","ar":"بانتظار أطلس"},"Each synchronization refreshes up to 20 shipments. Repeat for a larger list.":{"en":"Each synchronization refreshes up to 20 shipments. Repeat for a larger list.","fr":"Chaque synchronisation actualise jusqu’à 20 colis. Répétez pour une liste plus longue.","ar":"كل مزامنة كتحدّث حتى لـ20 كولي. عاود المزامنة إلا كانت اللائحة كبر."},"Some Atlas shipments could not be refreshed. Try synchronizing again.":{"en":"Some Atlas shipments could not be refreshed. Try synchronizing again.","fr":"Certains colis Atlas n’ont pas pu être actualisés. Relancez la synchronisation.","ar":"بعض الكوليات ما تحدّثوش من أطلس. عاود المزامنة."},"Net profit includes purchase costs, Atlas transport fees, commissions and advertising.":{"en":"Net profit includes purchase costs, Atlas transport fees, commissions and advertising.","fr":"Le profit net inclut les coûts d’achat, les frais de transport Atlas, les commissions et la publicité.","ar":"الربح الصافي كيحسب تكلفة الشراء ومصاريف نقل أطلس والعمولات والإشهار."},"Transport costs are managed by Atlas.":{"en":"Transport costs are managed by Atlas.","fr":"Les frais de transport sont gérés par Atlas.","ar":"مصاريف النقل كتتاخد من أطلس."},"Atlas transport":{"en":"Atlas transport","fr":"Transport Atlas","ar":"نقل أطلس"},"From Atlas automatically":{"en":"From Atlas automatically","fr":"Automatiquement depuis Atlas","ar":"تلقائياً من أطلس"}});
Object.assign(translations,{Atlas:{fr:'Atlas',en:'Atlas',ar:'أطلس'}});
Object.assign(translations,{"Edit team account":{"en":"Edit team account","fr":"Modifier le sous-compte","ar":"تعديل حساب البنت"},"Account enabled":{"en":"Account enabled","fr":"Compte actif","ar":"الحساب مفعّل"},"Existing orders, commissions, payments and assigned ads remain linked to this account.":{"en":"Existing orders, commissions, payments and assigned ads remain linked to this account.","fr":"Les commandes, commissions, paiements et publicités attribuées restent liés à ce compte.","ar":"الطلبات والعمولات والأداءات والإشهار المرتبطين بهاد الحساب كيبقاو محفوظين."},"Changing the login email also requires updating private site sharing. This form does not change site sharing or send invitations.":{"en":"Changing the login email also requires updating private site sharing. This form does not change site sharing or send invitations.","fr":"Après un changement d’email, mettez aussi à jour le partage privé du site. Ce formulaire ne modifie pas le partage et n’envoie pas d’invitation.","ar":"إلا بدّلتي الإيميل، خاصك تحدّث حتى المشاركة الخاصة ديال الموقع. هاد الفورم ما كيبدّلش المشاركة وما كيسيفطش الدعوات."},"Team account changed. Refresh and try again.":{"en":"Team account changed. Refresh and try again.","fr":"Ce sous-compte a changé. Actualisez et réessayez.","ar":"هاد الحساب تبدّل. حدّث الصفحة وعاود المحاولة."},"Email already used or team account could not be saved.":{"en":"Email already used or team account could not be saved.","fr":"Email déjà utilisé ou modification du sous-compte impossible.","ar":"الإيميل مستعمل أو تعذّر حفظ تعديل الحساب."}});

Object.assign(translations,{"Refreshes every 30 seconds while this page is open.":{en:"Refreshes every 30 seconds while this page is open.",fr:"Actualisation automatique toutes les 30 secondes quand cette page est ouverte.",ar:"كيتحدّث تلقائياً كل 30 ثانية ملي هاد الصفحة محلولة."}});

Object.assign(translations,{"Select an Atlas city before saving.":{en:"Select an Atlas city before saving.",fr:"Sélectionnez une ville Atlas avant d’enregistrer.",ar:"اختار مدينة من أطلس قبل تسجيل الطلبية."},"Atlas cities are unavailable. Refresh before saving.":{en:"Atlas cities are unavailable. Refresh before saving.",fr:"Les villes Atlas sont indisponibles. Actualisez avant d’enregistrer.",ar:"مدن أطلس غير متاحة. حدّث الاتصال قبل التسجيل."},"Order saved. Atlas transmission needs a retry.":{en:"Order saved. Atlas transmission needs a retry.",fr:"Commande enregistrée. Réessayez la transmission à Atlas depuis son détail.",ar:"تسجلات الطلبية. عاود الإرسال لأطلس من تفاصيلها."}});

